SELECT r.id, me.id, v.group_value, v.rank_from, v.rank_to, v.soft, v.hard, v.applies, v.notes
FROM compliance.rules r
JOIN (VALUES
    ('FUND_SECTOR_BOOK_PCT', 'HALY-FUND-HSI-INST', NULL::text, NULL::int, NULL::int, 20::numeric, 25::numeric, TRUE, 'Harbor institutional default sector cap'),
    ('FUND_SECTOR_BOOK_PCT', 'HALY-FUND-HSI-INST', 'Industrial distribution', NULL::int, NULL::int, 35::numeric, 45::numeric, TRUE, 'Industrial distribution is allowed a wider share'),
    ('FUND_SECTOR_BOOK_PCT', 'HSCF2-FUND', 'Industrials', NULL::int, NULL::int, 18::numeric, 20::numeric, TRUE, 'Tighter industrials cap than the rule default'),
    ('FUND_SECTOR_BOOK_PCT', 'HALY-FUND-POC', NULL::text, NULL::int, NULL::int, NULL::numeric, NULL::numeric, FALSE, 'Pioneer does not use the sector test'),
    ('FUND_SECTOR_BOOK_PCT', 'HALY-FUND-POC-MAIN', NULL::text, NULL::int, NULL::int, NULL::numeric, NULL::numeric, FALSE, 'Pioneer sleeve does not use the sector test'),
    ('FUND_SECTOR_BOOK_PCT', 'HALY-FUND-POC-OVS', NULL::text, NULL::int, NULL::int, NULL::numeric, NULL::numeric, FALSE, 'Pioneer sleeve does not use the sector test'),
    ('FUND_ISSUER_NAV_PCT', 'HSCF2-FUND', NULL::text, NULL::int, NULL::int, 12::numeric, 15::numeric, TRUE, 'Halyard single-name cap, maintained on the fund'),
    ('FUND_ISSUER_NAV_PCT', 'HALY-FUND-HSI-INST', NULL::text, 1, 1, 6::numeric, 8::numeric, TRUE, 'Largest issuer'),
    ('FUND_ISSUER_NAV_PCT', 'HALY-FUND-HSI-INST', NULL::text, 2, 4, 2.4::numeric, 3::numeric, TRUE, 'Next three issuers'),
    ('FUND_ISSUER_NAV_PCT', 'HALY-FUND-HSI-INST', NULL::text, 5, NULL::int, 1::numeric, 1.5::numeric, TRUE, 'Every issuer after the top four')
